import {retrieve,simulate} from './engine.mjs';
export const demoPlan={device:'2N7000',vds:48,vgs:0,temperature:25,limit:1,compliance:100,settling:1,samples:20,connections:true};
export const stepLabels=['Request','Clarify','Evidence','Plan','Result'];
export function guideState(step,scenario='nominal',corpus){if(!Number.isInteger(step)||step<0||step>4)throw new Error('Invalid guide step');return {step,label:stepLabels[step],evidence:step>=2?retrieve('2N7000 IDSS off-state drain leakage',corpus,'hybrid',1):[],run:step===4?simulate(demoPlan,scenario):null};}
export function initializeGuide(corpus,{renderEvidence,escape,openWorkbench}){
 const $=s=>document.querySelector(s);let step=0,scenario='nominal';const esc=escape;
 function render(){const state=guideState(step,scenario,corpus);$('#guide-progress').innerHTML=stepLabels.map((name,i)=>`<button data-step="${i}" class="${i===step?'active':''}" ${i===step?'aria-current="step"':''}>${i+1}. ${name}</button>`).join('');$('#guide-progress').querySelectorAll('button').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);render();});
 const screens=[
 `<p class="eyebrow">STEP 1 / A CUSTOMER GOAL</p><h2>“Check that it doesn’t leak too much.”</h2><div class="request-bubble">“Check the off-state leakage on this 2N7000. Use our usual limit.”</div><p>The goal is understandable. The instructions are incomplete: which current, under what conditions, and what does “usual” mean?</p><div class="guide-outcome"><strong>The tool should not guess.</strong><br>Its first job is to expose what the engineer still needs to know.</div>`,
 `<p class="eyebrow">STEP 2 / MAKE THE REQUEST SPECIFIC</p><h2>Ask the questions that change the test.</h2><ul class="guide-list"><li><strong>Which leakage?</strong> For this scenario, the customer confirms drain current with the gate held off: IDSS. Gate leakage would be a different test.</li><li><strong>Which conditions?</strong> Identify the applied voltage and temperature.</li><li><strong>Which acceptance rule?</strong> The customer chooses the published datasheet condition for this demonstration.</li></ul><p class="tiny">These are explicit scenario clarifications. The prototype has not automatically inferred the customer's private requirements.</p>`,
 `<p class="eyebrow">STEP 3 / SHOW THE SOURCE</p><h2>Find the relevant specification.</h2><p>The selected Vishay datasheet lists the 2N7000 off-state drain-current condition. The source stays visible so an engineer can inspect the exact row.</p><div class="condition-list"><div><strong>48 V</strong><span>Drain-to-source voltage</span></div><div><strong>0 V</strong><span>Gate-to-source voltage: gate held off</span></div><div><strong>25°C</strong><span>Default temperature in the table</span></div><div><strong>1 µA</strong><span>Maximum current at this condition</span></div></div><p class="tiny">One microampere is one millionth of an ampere. These values apply to the selected part and condition, not to every transistor.</p>`,
 `<p class="eyebrow">STEP 4 / KEEP THE PLAN TRACEABLE</p><h2>Separate documented values from chosen settings.</h2><div class="tablewrap"><table><thead><tr><th>Decision</th><th>Where it comes from</th></tr></thead><tbody><tr><td>48 V, gate at 0 V, 25°C, maximum 1 µA</td><td>Selected datasheet condition</td></tr><tr><td>1-second delay, 20 readings, 100 µA current cap</td><td>Illustrative simulation settings</td></tr><tr><td>Drain, source, and gate connections</td><td>Logical setup for this scenario; physical wiring needs review</td></tr></tbody></table></div><p>The configuration form blocks incomplete or unsupported plans. A real engineer would verify the instrument settings and settling time before a hardware test.</p><div class="guide-outcome"><strong>Next:</strong> Execute the complete demo plan in a software simulator.</div>`,
 `<p class="eyebrow">STEP 5 / INTERPRET THE RESULT</p><h2>A reading needs context.</h2><p>Choose a synthetic scenario to see why an engineering assistant must distinguish a result from a diagnosis.</p><div class="guide-scenarios"><button data-scenario="nominal">Normal device</button><button data-scenario="leaky">Leaky device</button><button data-scenario="fixture">Leaky test fixture</button><button data-scenario="compliance">Current cap reached</button></div><div id="guide-run"></div><details><summary>View the simulator’s command trace</summary><pre>${esc(state.run?.trace.join('\n')||'')}</pre></details><button id="guide-open-workbench">Configure your own test</button>`];
 $('#guide-stage').innerHTML=screens[step];$('#guide-back').disabled=step===0;$('#guide-next').disabled=step===4;$('#guide-next').textContent=['Find what is missing','Find the specification','Build the test plan','Run the simulated test','Demo complete'][step];
 $('#guide-proof').innerHTML=step>=2?renderEvidence(state.evidence[0]):'<div class="notice warn"><h3>Clarify before choosing a limit</h3><p>“Our usual limit” is not available in the public documents. It must be supplied or replaced with an explicitly agreed condition.</p></div>';
 if(step===4){const r=state.run;const explanations={nominal:'All simulated readings stay below the selected 1 µA threshold. This illustrates a passing comparison, not a real device qualification.',leaky:'At least one simulated reading exceeds the limit. The scenario supplies excessive device leakage; a real reading would still require investigation.',fixture:'The device is nominal in this scenario, but the connection fixture adds current. A failed comparison alone cannot tell you which component is responsible.',compliance:'The simulator reaches its configured current cap and stops acquisition. This is an invalid measurement, not a trustworthy pass or fail.'};$('#guide-run').innerHTML=`<div class="guide-number">${r.status==='PASS'?'Within the limit':r.status==='FAIL'?'Above the limit':'Measurement stopped'}</div><p>Simulated mean: <strong>${r.mean_uA.toFixed(3)} µA</strong> · limit: <strong>1 µA</strong></p><div class="guide-outcome">${esc(explanations[scenario])}</div><p class="tiny">Synthetic illustrative readings · output switched off at the end of every run.</p>`;document.querySelectorAll('[data-scenario]').forEach(b=>{b.classList.toggle('selected',b.dataset.scenario===scenario);b.onclick=()=>{scenario=b.dataset.scenario;render();};});$('#guide-open-workbench').onclick=openWorkbench;}
 }
 $('#guide-next').onclick=()=>{step=Math.min(4,step+1);render();};$('#guide-back').onclick=()=>{step=Math.max(0,step-1);render();};$('#guide-reset').onclick=()=>{step=0;scenario='nominal';render();};render();
}
